insert into public.sapa_pic_settings(pic_name,setting_key,value) select p.name,d.key,d.value from public.sapa_pic_profiles p cross join jsonb_each($pod_defaults${"podTemplate":"Halo Selamat {waktu_salam} Pak/Bu {nama_ac},\n\nIzin menginfokan dan mengingatkan untuk operasional toko binaan Bapak/Ibu saat ini terdapat *{jumlah_shipment} pesanan* Alfagift yang masih perlu diselesaikan proses *POD (Proof of Delivery)*.\n\nMohon bantuannya untuk dikoordinasikan ke tim toko agar segera diselesaikan konfirmasi POD-nya hari ini ya Pak/Bu, agar pesanan tidak menggantung.\n\nTerima kasih banyak atas perhatian dan kerja samanya! 🙏","podDelay":8,"podUseSameTab":true,"podSoundEnabled":true}$pod_defaults$::jsonb) d on conflict (pic_name,setting_key) do nothing;
